  function pickSlot(index){const c=controllers.defender,g=c.engine;if(g.paused||!['build','wave'].includes(g.phase))return;if(!c.started)start();c.view.hoverSlot=index;const t=g.occupied(index);if(t){c.view.selectedTower=t.id;render();return;}c.view.selectedTower=null;const type=c.view.selectedType;if(g.money<g.cost(type)){toast('Na tuto obranu chybí '+(g.cost(type)-g.money)+' podpory.');return;}g.build(index,type);events();render();}
  const canvas=$('defender-canvas');
  function pointerSlot(e){const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*960,y=(e.clientY-r.top)/r.height*576;let index=-1,distance=Math.max(33,22*960/r.width);controllers.defender.engine.slots.forEach(([a,b],i)=>{const d=Math.hypot(x-a,y-b);if(d<distance){index=i;distance=d;}});return index;}
  canvas.addEventListener('pointermove',e=>{const c=controllers.defender,r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*960,y=(e.clientY-r.top)/r.height*576;c.view.hoverSlot=pointerSlot(e);c.view.hoverEnemy=c.engine.enemies.find(n=>Math.hypot(n.x-x,n.y-y)<24)?.id||null;});canvas.addEventListener('pointerleave',()=>{controllers.defender.view.hoverSlot=-1;controllers.defender.view.hoverEnemy=null;});canvas.addEventListener('click',e=>{const i=pointerSlot(e);if(i>=0)pickSlot(i);});
  function focusSignalTile(){const c=controllers.signal;if(c.engine.phase==='playing')$('pipe-grid').children[c.focus]?.focus({preventScroll:true});else $('board-overlay').querySelector('.primary-button')?.focus({preventScroll:true});}
  function turnSignal(index,direction){if(current!=='signal')return;const c=controllers.signal;if(!c.engine.turn(index,direction??c.direction))return;c.focus=index;events();render();focusSignalTile();}
  function undoSignal(){if(current!=='signal')return;const c=controllers.signal,index=c.engine.undoStack.at(-1)?.i;if(!c.engine.undo())return;c.focus=index;events();render();focusSignalTile();}
  function hintSignal(){if(current!=='signal')return;const c=controllers.signal,hint=c.engine.askHint();if(!hint)return;c.focus=hint.index;events();render();$('pipe-grid').children[c.focus]?.focus({preventScroll:true});}
  function nextSignalRound(){if(current!=='signal'||!game().next())return;controllers.signal.focus=game().source;overlayKey='';render();focusSignalTile();}
  $('pipe-grid').addEventListener('click',e=>{const b=e.target.closest('[data-tile]');if(b)turnSignal(Number(b.dataset.tile),e.shiftKey?-controllers.signal.direction:controllers.signal.direction);});
  $('pipe-grid').addEventListener('contextmenu',e=>{const b=e.target.closest('[data-tile]');if(b){e.preventDefault();turnSignal(Number(b.dataset.tile),-controllers.signal.direction);}});
  $('pipe-grid').addEventListener('keydown',e=>{
    const b=e.target.closest('[data-tile]');if(!b)return;const c=controllers.signal,g=c.engine,i=Number(b.dataset.tile),step={ArrowLeft:-1,ArrowRight:1,ArrowUp:-g.size,ArrowDown:g.size}[e.key];
    if(e.key==='Enter'){e.preventDefault();e.stopPropagation();turnSignal(i,e.shiftKey?-c.direction:c.direction);return;}
    if(step){e.preventDefault();e.stopPropagation();let next=i+step;while(next>=0&&next<g.tiles.length&&(Math.abs(step)===g.size||Math.floor(next/g.size)===Math.floor(i/g.size))){if(g.canTurn(next)){c.focus=next;render();focusSignalTile();break;}next+=step;}}
  });
